     a= xlsread('biteb.xlsx');
     data=a(:,1)';
     TTrain = floor(0.95*numel(data));
     dataTrain = data(1:TTrain+1);
     dataTest = data(TTrain+1:end);
     sig = std(dataTrain);
     Standardized = (dataTrain - mu) / sig;
     XTrain = Standardized(1:end-1);
     YTrain = Standardized(2:end);
     numFeatures = 1;
     numResponses = 1;
     numHiddenUnits = 200;
     layers = [ sequenceInputLayer(numFeatures) lstmLayer(numHiddenUnits)
     fullyConnectedLayer(numResponses) regressionLayer];
     options = trainingOptions('adam', ...
           'MaxEpochs',250, ...
           'GradientThreshold',1, ...
           'InitialLearnRate',0.005, ...
           'LearnRateSchedule','piecewise', ...
           'LearnRateDropPeriod',125, ...
           'LearnRateDropFactor',0.2, ...
           'Verbose',0, ...
           'Plots','training-progress');
     dataTestStandardized = (dataTest - mu) / sig;
     XTest = dataTestStandardized(1:end-1);
     net = predictAndUpdateState(net,XTrain);
     [net,YPred] = predictAndUpdateState(net,YTrain(end));
     numTimeStepsTest = numel(XTest);
     for i = 2:numTimeStepsTest
           [net,YPred(:,i)] = predictAndUpdateState(net,YPred(:,i-1),'ExecutionEnviron
           ment','cpu');
     End
     figure
     plot(YTest)
     hold on
     plot(YPred,'.-')
     hold off
     legend(["Observed" "Forecast"])；ylabel("Cases") title("Forecast")

Appendix 2
Introduce: Strategic planning code
     function [nn,bn,cn,an,sv]=strategy(x,t)
     a=1000;b=0;c=0;sx=1;sv=0;nn=[];bn=[];cn=[];an=[];sxf=0;
     bite = xlsread('bitezhen.xlsx');
     gold = xlsread('goldzhen.xlsx');
     by = xlsread('biteyuce.xlsx');
     hy = xlsread('goldyuce.xlsx');
     [a,b]=bitemai(a,bite(1));
     [bl,hl]=shoouyilv(x);
     sx=sx+1;
     n=1;nn=[nn,n];bn=[bn,b];cn=[cn,c];an=[an,a];
     for sx=2:t
           if hl(sx)>=bl(sx)
                 if hl(sx)>-0.01
                       k=a+b*bite(sx)*0.98-gold(sx)*0.99;
                       if k>=gold(sx)
                            a=0;b=0;
                            [a,c]=goldmai(a+b*bite(sx)*0.98,gold(sx));
                            if a==0
                                 n=2;
                            else
                                 if bl(sx)>0
                                       [a,b]=bitemai(a,bite(sx));n=4;
                                 else
                                       n=5;
                                 end
                            end
                       else
                            if c>0
                                 if bl(sx)>=0
                                      [a,b]=bitemai(a,bite(sx));n=4;
                                 else
                                       a=b*bite(sx)*0.98+a;b=0;n=5;
                                 end
                            else
                                 if bl(sx)>=0
                                       [a,b]=bitemai(a,bite(sx));n=1;
                                 else
                                       a=b*bite(sx)*0.98+a;b=0;n=3;
                                 end

                        end
                  end
           else
                  a=a+b*bite(sx)*0.98+c*gold(sx)*0.99;b=0;c=0;n=3;
           end
    else
           if bl(sx)>-0.02
                 [a,b1]=bitemai(a+c*gold(sx)*0.99,bite(sx));c=0;
                 b=b+b1; n=1;
           else
                 a=a+b*bite(sx)*0.98+c*gold(sx)*0.99;b=0;c=0;n=3;
           end
     end
     nn=[nn,n];
     bn=[bn,b];
     cn=[cn,c];
     an=[an,a];
sv=a+b*bite(sx)+c*gold(sx);
end
sv=sv-1000;
nn=nn';
an=an';
bn=bn';
cn=cn';
function [a,b]=bitemai(sv,x)
b=floor(sv*10/x)/10;n=0;
a=sv-x*b*1.02;
if a<0
     n=0.1;
     while n*x<(-a)
          n=n+0.1;
     end
end
b=b-n;
a=a+x*n;
function [a,b]=goldmai(sv,x)
b=floor(sv/x);n=0;
a=sv-x*b*1.01;
if a<0
     n=1;
     while n*x<(-a)
          n=n+1;

     end
end
b=b-n;
a=a+x*n;
function [blz,hlz]=shoouyilv(x)
blz=[0];hlz=[0];
by = xlsread('biteyuce.xlsx');
hy = xlsread('goldyuce.xlsx');
for sx=2:1255
     if sx-x>0
           bl=(by(sx)-by(sx-x))/by(sx-x);
           hl=(hy(sx)-hy(sx-x))/hy(sx-x);
     else
           bl=(by(sx)-by(1))/by(1);
           hl=(hy(sx)-hy(1))/hy(1);
     end
     blz=[blz,bl];hlz=[hlz,hl];
end
